create table if not exists public.attendance_notification_claims (organization_id uuid not null,schedule_id uuid not null,lesson_date date not null,claim_token uuid not null default gen_random_uuid(),claimed_at timestamptz not null default now(),primary key(organization_id,schedule_id,lesson_date)); alter table public.attendance_notification_claims enable row level security; revoke all on public.attendance_notification_claims from public,anon,authenticated; grant select,insert,delete on public.attendance_notification_claims to service_role; insert into public.attendance_notification_claims(organization_id,schedule_id,lesson_date) select distinct n.organization_id,s.id,(n.metadata->>'lesson_date')::date from public.system_notifications n join public.lesson_schedules s on s.id::text=n.entity_id and s.organization_id=n.organization_id where n.event_key='attendance_missing' and n.metadata->>'lesson_date' ~ '^\d{4}-\d{2}-\d{2}$' on conflict do nothing;
